#!/usr/bin/env python3
"""Generate Markdown status lists from CSV source files."""

from __future__ import annotations

import csv
from collections import defaultdict
from datetime import date
from io import StringIO
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"

NON_BREAKING_HYPHEN = "‑"
CSV_ENCODINGS = ("utf-8-sig", "cp1252")

EEP_LIST_HEADER = [
    "<!--",
    "GENERATED FILE - DO NOT EDIT MANUALLY",
    "",
    "Generated by:",
    "tools/generate_status_lists.py",
    "",
    "Source files:",
    "- docs/eep-list.csv",
    "",
    "Manual edits may be overwritten.",
    "-->",
    "",
    "# EEP List",
    "",
    "Overview of supported and planned EnOcean Equipment Profiles (EEP).",
    "",
]

DEVICE_LIST_HEADER = [
    "<!--",
    "GENERATED FILE - DO NOT EDIT MANUALLY",
    "",
    "Generated by:",
    "tools/generate_status_lists.py",
    "",
    "Source files:",
    "- docs/device-list.csv",
    "",
    "Manual edits may be overwritten.",
    "-->",
    "",
    "# Device List",
    "",
    "Overview of supported and planned EnOcean devices.",
    "",
]

PROPRIETARY_PROFILE_HEADER = [
    "<!--",
    "GENERATED FILE - DO NOT EDIT MANUALLY",
    "",
    "Generated by:",
    "tools/generate_status_lists.py",
    "",
    "Source files:",
    "- docs/proprietary-profile-list.csv",
    "",
    "Manual edits may be overwritten.",
    "-->",
    "",
    "# Proprietary Profile List",
    "",
    "Overview of implemented proprietary profiles and compatible devices.",
    "",
]


def has_x(row: dict[str, str]) -> bool:
    return any(value.strip().upper() == "X" for value in row.values())



def format_identifier(value: str) -> str:
    return value.replace("-", NON_BREAKING_HYPHEN)



def escape_md(value: str) -> str:
    return value.replace("|", "\\|").strip()



def format_cell(header: str, value: str) -> str:
    value = escape_md(value)

    if header in {"EEP", "Model", "Compatible Device", "Profile", "Proprietary Profile"}:
        value = format_identifier(value)

    return value



def read_csv_text(csv_path: Path) -> str:
    """Read CSV text with UTF-8 first and CP1252 fallback for Excel exports."""

    for encoding in CSV_ENCODINGS:
        try:
            return csv_path.read_text(encoding=encoding)
        except UnicodeDecodeError:
            continue

    encodings = ", ".join(CSV_ENCODINGS)
    raise UnicodeDecodeError(
        "utf-8-sig",
        b"",
        0,
        1,
        f"Could not decode {csv_path} using any supported encoding: {encodings}",
    )



def read_csv(csv_path: Path) -> tuple[list[str], list[dict[str, str]]]:
    csv_text = read_csv_text(csv_path)
    csv_stream = StringIO(csv_text)
    sample = csv_stream.read(4096)
    csv_stream.seek(0)
    dialect = csv.Sniffer().sniff(sample, delimiters=",;")
    reader = csv.DictReader(csv_stream, dialect=dialect)

    if not reader.fieldnames:
        raise ValueError(f"No header found in {csv_path}")

    headers = [h.strip() for h in reader.fieldnames]
    rows = []

    for raw_row in reader:
        row = {
            key.strip(): (value or "").strip()
            for key, value in raw_row.items()
            if key is not None
        }

        rows.append(row)

    return headers, rows



def generate_eep_table(csv_path: Path, md_path: Path) -> None:
    headers, rows = read_csv(csv_path)

    filtered_rows = [row for row in rows if has_x(row)]

    lines = list(EEP_LIST_HEADER)

    lines.extend(
        [
            "| " + " | ".join(headers) + " |",
            "|" + "|".join(["---"] * len(headers)) + "|",
        ]
    )

    for row in filtered_rows:
        lines.append(
            "| "
            + " | ".join(format_cell(header, row.get(header, "")) for header in headers)
            + " |"
        )

    lines.extend(["", f"_Last updated: {date.today().isoformat()}_", ""])

    md_path.write_text("\n".join(lines), encoding="utf-8")



def generate_device_table(csv_path: Path, md_path: Path) -> None:
    headers, rows = read_csv(csv_path)

    filtered_rows = [row for row in rows if has_x(row)]

    manufacturer_key = "Manufacturer"

    grouped: dict[str, list[dict[str, str]]] = defaultdict(list)

    for row in filtered_rows:
        grouped[row.get(manufacturer_key, "Unknown")].append(row)

    lines = list(DEVICE_LIST_HEADER)

    table_headers = [h for h in headers if h != manufacturer_key]

    for manufacturer in sorted(grouped.keys()):
        lines.extend(
            [
                f"**{manufacturer}**",
                "",
                "| " + " | ".join(table_headers) + " |",
                "|" + "|".join(["---"] * len(table_headers)) + "|",
            ]
        )

        for row in grouped[manufacturer]:
            lines.append(
                "| "
                + " | ".join(format_cell(header, row.get(header, "")) for header in table_headers)
                + " |"
            )

        lines.append("")

    lines.extend([f"_Last updated: {date.today().isoformat()}_", ""])

    md_path.write_text("\n".join(lines), encoding="utf-8")



def generate_proprietary_profile_table(csv_path: Path, md_path: Path) -> None:
    _, rows = read_csv(csv_path)

    grouped: dict[tuple[str, str], list[str]] = defaultdict(list)

    for row in rows:
        manufacturer = row.get("Manufacturer", "")
        profile = row.get("Proprietary Profile", "")
        device = row.get("Compatible Device", "")

        grouped[(manufacturer, profile)].append(device)

    lines = list(PROPRIETARY_PROFILE_HEADER)

    lines.extend(
        [
            "| Manufacturer | Profile | Compatible Devices |",
            "|---|---|---|",
        ]
    )

    for (manufacturer, profile), devices in sorted(grouped.items()):
        formatted_devices = "<br>".join(format_identifier(device) for device in devices)

        lines.append(
            f"| {manufacturer} | {format_identifier(profile)} | {formatted_devices} |"
        )

    lines.extend(["", f"_Last updated: {date.today().isoformat()}_", ""])

    md_path.write_text("\n".join(lines), encoding="utf-8")



def main() -> None:
    generate_eep_table(
        DOCS / "eep-list.csv",
        DOCS / "eep-list.md",
    )

    generate_device_table(
        DOCS / "device-list.csv",
        DOCS / "device-list.md",
    )

    generate_proprietary_profile_table(
        DOCS / "proprietary-profile-list.csv",
        DOCS / "proprietary-profile-list.md",
    )


if __name__ == "__main__":
    main()
